import React from "react";
import GoalCard from "./GoalCard";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";

const Dashboard = ({ goals, income, onRemoveGoal, onShowGoalForm, onEditGoal, totalMonthlyNeeded, sortBy, setSortBy, onShowGoalWizard, setGoals }) => {
  // Only allow drag-and-drop when sorting by priority
  const isDraggable = sortBy === "priority";

  const handleDragEnd = (result) => {
    if (!result.destination) return;
    const reordered = Array.from(goals);
    const [removed] = reordered.splice(result.source.index, 1);
    reordered.splice(result.destination.index, 0, removed);
    // Update priorities based on new order
    const updated = reordered.map((g, idx) => ({ ...g, priority: idx + 1 }));
    setGoals(updated);
  };

  return (
    <div>
      <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-8 gap-4">
        <div className="bg-gradient-to-r from-blue-200 via-white to-emerald-100 rounded-lg px-6 py-4 shadow">
          <div className="text-lg font-semibold text-blue-900">Total Savings Needed</div>
          <div className="text-2xl font-bold text-primary">${goals.reduce((sum, g) => sum + g.amount, 0).toLocaleString()}</div>
        </div>
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-r from-emerald-100 via-white to-blue-100 rounded-lg px-4 py-2 shadow text-sm">
            <span className="font-semibold text-emerald-700">Monthly Disposable Income:</span> <span className="text-blue-900">${income.toLocaleString()}</span>
          </div>
          <button
            className="bg-gradient-to-r from-primary to-emerald-400 text-white px-4 py-2 rounded font-semibold shadow hover:bg-blue-600"
            onClick={onShowGoalForm}
          >
            + Add Goal (Form)
          </button>
          <button
            className="bg-gradient-to-r from-emerald-400 to-primary text-white px-4 py-2 rounded font-semibold shadow hover:bg-emerald-600"
            onClick={onShowGoalWizard}
          >
            + Add Goal (Step-by-step)
          </button>
        </div>
      </div>
      <div className="mb-4 flex flex-col sm:flex-row items-center gap-4 justify-between">
        <h2 className="text-2xl font-bold text-primary tracking-tight">Your Goals</h2>
        <div className="flex items-center gap-2">
          <label className="font-medium text-blue-900">Sort by:</label>
          <select
            className="border rounded px-2 py-1 text-blue-900 bg-white shadow-sm focus:ring-2 focus:ring-primary"
            value={sortBy}
            onChange={e => setSortBy(e.target.value)}
          >
            <option value="priority">Priority</option>
            <option value="deadline-soonest">Deadline (soonest -&gt; furthest)</option>
            <option value="deadline-furthest">Deadline (furthest -&gt; soonest)</option>
          </select>
        </div>
      </div>
      <div className="mb-8">
        <div className="bg-gradient-to-r from-blue-50 via-white to-emerald-50 rounded-lg p-4 shadow flex flex-col md:flex-row md:items-center md:justify-between gap-2">
          <div className="text-sm font-medium">Total Saved: <span className="text-primary font-bold">${goals.reduce((sum, g) => sum + g.saved, 0).toLocaleString()}</span></div>
          <div className="text-sm font-medium">Progress: <span className="text-primary font-bold">{goals.length ? Math.round(goals.reduce((sum, g) => sum + g.saved, 0) / goals.reduce((sum, g) => sum + g.amount, 0) * 100) : 0}%</span></div>
          <div className="text-sm font-medium">Monthly Savings Needed: <span className="text-primary font-bold">${totalMonthlyNeeded ? totalMonthlyNeeded.toLocaleString() : 0}</span></div>
          <div className={`text-sm font-medium ${income < totalMonthlyNeeded ? 'text-red-500' : 'text-green-600'}`}>Savings vs Income: <span className="font-bold">{income < totalMonthlyNeeded ? 'Not enough income' : 'On track'}</span></div>
        </div>
      </div>
      {isDraggable ? (
        <DragDropContext onDragEnd={handleDragEnd}>
          <Droppable droppableId="goals-list">
            {(provided) => (
              <div className="flex flex-col gap-4 items-center w-full" ref={provided.innerRef} {...provided.droppableProps}>
                {goals.map((goal, idx) => (
                  <Draggable key={goal.id} draggableId={goal.id} index={idx}>
                    {(provided, snapshot) => (
                      <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        {...provided.dragHandleProps}
                        className={`transition-all w-full max-w-lg ${snapshot.isDragging ? 'scale-105 shadow-2xl z-20' : ''}`}
                      >
                        <GoalCard goal={goal} onRemove={onRemoveGoal} onEdit={onEditGoal} priorityRank={idx + 1} />
                      </div>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        </DragDropContext>
      ) : (
        <div className="flex flex-col gap-4 items-center w-full">
          {goals.map((goal, idx) => (
            <GoalCard key={goal.id} goal={goal} onRemove={onRemoveGoal} onEdit={onEditGoal} priorityRank={idx + 1} />
          ))}
        </div>
      )}
    </div>
  );
};

export default Dashboard;
